'use strict';
const $=id=>document.getElementById(id);
const state={token:window.__workspaceToken||'',busy:false,lookup:null,currentJob:null,credits:null,slideSeq:0,activeSlide:null,records:new Map(),diagnosticSessionId:null,clientStartedAt:new Date().toISOString(),clientEvents:[],clientSeq:0,prospect:{loaded:false,group:'flagged',groups:null,capabilities:null,selected:new Set(),jobId:null,job:null,results:[],polling:false}};delete window.__workspaceToken;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200)}
async function api(path,body){if(!state.token){location.replace('/');throw new Error('Enter your password to open the app.')}const response=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${state.token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(65000),cache:'no-store'});let result;try{result=await response.json()}catch{throw new Error('The server returned an unreadable response.')}if(!response.ok){const err=new Error(result.error||'The request could not be completed.');err.payload=result;throw err}return result}
function clientEvent(name,details={}){const row={seq:++state.clientSeq,at:new Date().toISOString(),name,details};state.clientEvents.push(row);if(state.clientEvents.length>1000)state.clientEvents.shift();if(state.token)fetch('/v1/diagnostics/event',{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/json'},body:JSON.stringify({name,details}),cache:'no-store'}).catch(()=>{});return row}
async function resetDiagnosticSession(reason='workspace_load'){try{const r=await api('/v1/diagnostics/reset',{reason});state.diagnosticSessionId=r.sessionId;state.clientEvents=[];state.clientSeq=0;clientEvent('diagnostic_session_started',{reason,sessionId:r.sessionId,build:r.build||null});return r}catch(error){clientEvent('diagnostic_session_reset_failed',{reason,message:error.message});return null}}
function browserSnapshot(){return{sessionId:state.diagnosticSessionId,clientStartedAt:state.clientStartedAt,generatedAt:new Date().toISOString(),location:{path:location.pathname,visibility:document.visibilityState},navigator:{userAgent:navigator.userAgent,language:navigator.language,platform:navigator.platform},displayedCredits:state.credits,activeSlideId:state.activeSlide?.id||null,records:[...state.records.entries()].map(([id,r])=>({id,url:r.url||null,status:r.job?.status||null,routeId:r.job?.routeId||null,creditDelta:r.job?.creditDelta??null,requestIds:r.job?.requestIds||[]})),events:state.clientEvents}}
async function deepDiagnosticReport(job=null){const server=await api('/v1/diagnostics/report');return JSON.stringify({...server,browser:browserSnapshot(),activeJob:job||state.currentJob||null,warning:'API/auth secrets are redacted. Contact data and provider payloads are intentionally preserved for debugging.'},null,2)}
async function copyDeepDiagnosticReport(job=null){const text=await deepDiagnosticReport(job);await navigator.clipboard.writeText(text);clientEvent('diagnostic_report_copied',{bytes:text.length,activeJobStatus:(job||state.currentJob)?.status||null});return text}
function downloadDeepDiagnosticReport(){deepDiagnosticReport().then(text=>{const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`prospecting-beast-diagnostic-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);clientEvent('diagnostic_report_downloaded',{bytes:text.length})}).catch(e=>toast(e.message))}
function validLinkedIn(value){try{const u=new URL(value);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname)||!/^\/in\/[^/]+\/?$/i.test(u.pathname))throw Error();u.hostname='www.linkedin.com';u.search='';u.hash='';if(!u.pathname.endsWith('/'))u.pathname+='/';return u.href}catch{return null}}
function initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function timeLabel(iso){if(!iso)return'—';const d=new Date(iso);if(Number.isNaN(+d))return'—';return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function ageLabel(iso){if(!iso)return'not available';const ms=Date.now()-new Date(iso).getTime();if(!Number.isFinite(ms)||ms<0)return'just now';const s=Math.floor(ms/1000);if(s<5)return'just now';if(s<60)return`${s}s ago`;return`${Math.floor(s/60)}m ago`}
function updateCredits(summary){
  if(!summary){$('credits').hidden=true;clientEvent('credit_indicator_hidden',{reason:'missing_summary'});return}
  state.credits=summary;$('credits').hidden=false;const total=summary.totalCreditsRemaining;const routes=Array.isArray(summary.routes)?summary.routes:[];const freshest=routes.map(r=>r.observedAt).filter(Boolean).sort().at(-1);
  $('credits-label').textContent=total==null?'Credits unavailable':`${Number(total).toLocaleString()} total`;
  $('credits').title=total==null?'A fresh Seamless balance could not be confirmed for every configured organization.':`Total across ${routes.length} configured Seamless organization${routes.length===1?'':'s'} · ${ageLabel(freshest)}`;
  clientEvent('credit_indicator_rendered',{displayedTotal:Number.isFinite(total)?total:null,allFresh:summary.allFresh===true,activeRouteId:summary.activeRouteId||null,routes:routes.map(r=>({id:r.id,keySource:r.keySource,creditsRemaining:Number.isFinite(r.creditsRemaining)?r.creditsRemaining:null,fresh:r.fresh===true,usageState:r.usageState,observedAt:r.observedAt||null}))});renderCreditsDialog()
}
function renderCreditsDialog(){
  const summary=state.credits||{},routes=Array.isArray(summary.routes)?summary.routes:[];
  const rows=routes.map(r=>{const usage=r.usageState||'STANDBY';const cls=usage==='ACTIVE'?'active':usage==='EXHAUSTED'?'exhausted':usage==='UNAVAILABLE'?'bad':'standby';const orgLabel=(r.id||'route').toUpperCase()==='PRIMARY'?'Primary org balance':'Secondary org balance';return `<div class="credit-route ${cls}"><div><strong>${esc(orgLabel)}</strong><small>${esc(r.keySource||'Seamless API key')}</small></div><div><strong>${Number.isFinite(r.creditsRemaining)?Number(r.creditsRemaining).toLocaleString():'—'}</strong><small>${r.fresh?'X-PublicAPI-Credits':'unavailable'}</small></div><div class="credit-time"><strong>${esc(timeLabel(r.observedAt))}</strong><small>${esc(ageLabel(r.observedAt))}</small></div><span class="route-state ${cls}">${esc(usage)}</span>${r.error?`<small class="route-error">${esc(r.error)}</small>`:''}</div>`}).join('');
  const allFresh=summary.allFresh===true,count=routes.length;
  $('credits-content').innerHTML=`<div class="credit-number ${allFresh?'':'uncertain'}"><strong>${allFresh&&Number.isFinite(summary.totalCreditsRemaining)?Number(summary.totalCreditsRemaining).toLocaleString():'—'}</strong><span>${allFresh?`total across ${count} configured Seamless organization${count===1?'':'s'}`:'total withheld because every configured organization did not return a fresh credit header'}</span></div><div class="route-policy"><strong>PRIMARY-first</strong><span>New enrichment stays on PRIMARY while its fresh org balance is above 0. SECONDARY is used only after PRIMARY is confirmed exhausted or explicitly rejected for insufficient credits.</span></div><div class="credit-route-list">${rows||'<p class="fineprint">No Seamless routes were returned.</p>'}</div><div class="credit-facts"><div><span>Provider source</span><strong>X-PublicAPI-Credits</strong></div><div><span>Meaning</span><strong>Research credits remaining for org</strong></div><div><span>Refresh</span><strong>Every 15s + after enrichment</strong></div><div><span>Local fallback</span><strong>Never used as fresh balance</strong></div></div><p class="fineprint">Seamless documents this header as the remaining research-credit balance for the authenticated organization. The combined number is a sum of the configured key balances and is valid when those keys belong to distinct organizations. If a fresh probe fails or omits the header, Beast shows unavailable instead of guessing.</p>`;
}
function diagnosticDrawer(job){const count=Array.isArray(job?.diagnosticTrace)?job.diagnosticTrace.length:0;return `<details class="data-drawer diagnostic-drawer"><summary><span>Deep diagnostic trace</span><b>${count}</b></summary><div class="drawer-content diagnostic-content"><p>Copies the full server-wide diagnostic session: credit indicator probes, route decisions, cache/storage events, research POST, every poll, provider headers/bodies, parsed contact fields and browser/UI events.</p><button type="button" class="diagnostic-copy" data-copy-diagnostic="1">Copy FULL diagnostic report</button><small>No extra Seamless research request is made for diagnostics. Secrets are redacted; contact data is preserved.</small></div></details>`}
function displayPhone(value){return typeof value==='string'&&value.startsWith('+')?`0${value}`:String(value||'')}
function displayMethodValue(m){return m?.kind==='phone'?displayPhone(m.value):String(m?.value||'')}
function copyButton(value){return value?`<button class="copy-button" data-copy="${esc(value)}">Copy</button>`:''}
function methodMeta(m){const bits=[];if(m.label)bits.push(m.label);if(m.selected)bits.push('selected');if(m.status==='valid')bits.push('valid');if(Number(m.score)>0)bits.push(`${Number(m.score)}%`);return bits.join(' · ')}
function methodRows(label,methods){const arr=Array.isArray(methods)?methods:[];if(!arr.length)return'';return `<section class="method-group"><div class="method-group-head"><strong>${esc(label)}</strong><span>${arr.length}</span></div><div class="method-grid">${arr.map(m=>{const shown=displayMethodValue(m),meta=methodMeta(m);return `<div class="method-row"><div><span class="method-type">${m.kind==='email'?'EMAIL':'PHONE'}${meta?` · ${esc(meta)}`:''}</span>${m.kind==='email'?`<a href="mailto:${esc(m.value)}">${esc(shown)}</a>`:`<a href="tel:${esc(m.value)}">${esc(shown)}</a>`}${m.companyName?`<small>${esc(m.companyName)}</small>`:''}</div>${copyButton(shown)}</div>`}).join('')}</div></section>`}
function historyDrawer(data){const rows=Array.isArray(data.jobHistory)?data.jobHistory:[];if(!rows.length)return'';return `<details class="data-drawer"><summary><span>Employment history</span><b>${rows.length}</b></summary><div class="drawer-content history-pills">${rows.map(r=>`<div class="history-pill"><strong>${esc(r.companyName||'Company')}</strong>${r.title?`<span>${esc(r.title)}</span>`:''}<small>No company-specific phone/email mapping was supplied for this historical role.</small></div>`).join('')}</div></details>`}
function otherDrawer(methods){const arr=Array.isArray(methods)?methods:[];if(!arr.length)return'';return `<details class="data-drawer"><summary><span>Other provider candidates</span><b>${arr.length}</b></summary><div class="drawer-content provider-candidates">${arr.map(m=>{const shown=displayMethodValue(m);return `<div class="candidate-row"><div><strong>${esc(shown)}</strong><span>${esc([m.label,m.status,m.score?`${m.score}%`:null].filter(Boolean).join(' · ')||'Provider candidate')}</span>${m.companyName?`<small>${esc(m.companyName)}</small>`:''}${m.reason?`<em>${esc(m.reason)}</em>`:''}</div>${copyButton(shown)}</div>`}).join('')}</div></details>`}
function creditAuditLine(job,cached=false){if(cached)return'<span class="audit-chip ok">Cache · 0 new research requests</span>';const d=job.creditDelta;if(d===1)return'<span class="audit-chip ok">1 credit observed</span>';if(d===0)return'<span class="audit-chip ok">0-credit delta observed</span>';if(Number.isFinite(d)&&d>1)return`<span class="audit-chip danger">Credit anomaly · ${esc(d)} credits</span>`;return'<span class="audit-chip">Credit debit reconciling</span>'}
function companyChooser(data,record){const options=Array.isArray(data.companyContexts)?data.companyContexts:[];if(options.length<=1)return'';const selected=record?.companyContext||0;return `<div class="company-context"><div class="company-context-head"><span>MULTIPLE ROLES</span><small>Choose context · 0 credits</small></div><div class="company-options">${options.map((c,i)=>`<button type="button" data-company-context="${i}" class="company-option ${i===selected?'selected':''}"><span>${c.current?'CURRENT':'HISTORY'}</span><strong>${esc(c.companyName)}</strong></button>`).join('')}</div><div class="company-context-note">${selectedCompanyNote(data,selected)}</div></div>`}
function selectedCompanyNote(data,index=0){const options=Array.isArray(data.companyContexts)?data.companyContexts:[],selected=options[index]||options[0];if(!selected)return'';return selected.current?`Current Seamless record: ${esc(selected.companyName)}.`:`${esc(selected.companyName)} is historical. Returned emails/phones are not automatically attributed to that former role.`}
function newSlide(url){const feed=$('result-feed');const welcome=$('welcome-slide');if(welcome)welcome.remove();const slide=document.createElement('article');slide.className='result-slide';slide.id=`result-${++state.slideSeq}`;slide.dataset.url=url;slide.innerHTML='<div class="slide-card"><div class="loading-line"></div></div>';feed.append(slide);state.activeSlide=slide;state.records.set(slide.id,{job:null,companyContext:0,url});requestAnimationFrame(()=>slide.scrollIntoView({behavior:'smooth',block:'start'}));return slide}
function registerJob(slide,job){const rec=state.records.get(slide.id)||{companyContext:0,url:slide.dataset.url};rec.job=job;state.records.set(slide.id,rec);if(slide===state.activeSlide)state.currentJob=job;return rec}
function renderProcessing(job,slide=state.activeSlide){if(!slide)return;registerJob(slide,job);slide.innerHTML=`<div class="slide-card processing-card"><div class="processing-top"><div class="linkedin-badge large">in</div><div><span class="section-kicker">ENRICHING EXACT PROFILE</span><h2>Finding contact details…</h2><p>${esc(job.normalizedUrl||slide.dataset.url||'')}</p></div><span class="research-status"><i></i> Live</span></div><div class="progress-rail"><span></span></div><div class="processing-steps"><span class="done">✓ Profile submitted</span><span>↻ Polling one request</span><span>✦ Organizing result</span></div><div class="processing-foot">No search fan-out · no automatic duplicate submission · ${esc(job.keySource||job.routeId||'active organization')}</div></div>`}
function renderCompleted(job,cached=false,slide=state.activeSlide){
  if(!slide)return;const record=registerJob(slide,job);record.companyContext=record.companyContext||0;const d=job.data||{};const person=Array.isArray(d.personMethods)?d.personMethods:[];const current=Array.isArray(d.currentCompanyMethods)?d.currentCompanyMethods:[];const other=Array.isArray(d.otherCandidates)?d.otherCandidates:[];
  slide.innerHTML=`<div class="slide-card contact-card"><div class="contact-top"><div class="avatar">${esc(initials(d.fullName))}</div><div class="contact-title"><span>${cached?'CACHED CONTACT':'ENRICHED CONTACT'}</span><h2>${esc(d.fullName||'Contact')}</h2><p>${esc(d.company||'Company not returned')}</p></div><div class="contact-actions">${creditAuditLine(job,cached)}<span class="route-chip">${esc((job.routeId||'primary').toUpperCase())}</span></div></div>${companyChooser(d,record)}<div class="contact-grid"><div class="contact-column">${methodRows(`Current company · ${d.company||'Unknown'}`,current)||'<div class="empty-method">No current-company contact data returned.</div>'}</div><div class="contact-column">${methodRows('Personal / direct',person)||'<div class="empty-method">No personal/direct contact data returned.</div>'}</div></div><div class="drawer-row">${otherDrawer(other)}${historyDrawer(d)}</div><div class="slide-footer"><span>${esc(job.normalizedUrl||d.linkedinUrl||slide.dataset.url||'')}</span><span>Scroll ↑ for previous contact</span></div></div>`;
  const note=slide.querySelector('.company-context-note');if(note)note.innerHTML=selectedCompanyNote(d,record.companyContext);requestAnimationFrame(()=>slide.scrollIntoView({behavior:'smooth',block:'start'}));
}
function renderFailure(job,slide=state.activeSlide){if(!slide)return;registerJob(slide,job);slide.innerHTML=`<div class="slide-card failure-card"><div class="error-icon">!</div><div><span class="section-kicker">NO AMBIGUOUS RETRY</span><h2>Research needs attention</h2><p>${esc(job.message||`Research ended with status: ${job.status}.`)}</p></div></div>`}
async function pollUntilDone(job,url,slide){clientEvent('poll_loop_started',{url,status:job.status,requestIds:job.requestIds||[],routeId:job.routeId||null});if(job.status==='done'){renderCompleted(job,Boolean(job.cached),slide);clientEvent('poll_loop_short_circuit_done',{url,cached:Boolean(job.cached)});return}if(!['submitting','processing'].includes(job.status)){renderFailure(job,slide);clientEvent('poll_loop_short_circuit_terminal',{url,status:job.status});return}renderProcessing(job,slide);for(let i=0;i<40&&['submitting','processing'].includes(job.status);i++){await new Promise(r=>setTimeout(r,2500));clientEvent('poll_request_started',{url,iteration:i+1,requestIds:job.requestIds||[]});job=await api('/v1/person/research/status',{linkedinUrl:url});clientEvent('poll_response_received',{url,iteration:i+1,status:job.status,providerStatus:job.providerStatus||null,routeId:job.routeId||null,afterCredits:job.afterCredits??null,creditDelta:job.creditDelta??null,requestIds:job.requestIds||[]});if(['submitting','processing'].includes(job.status))renderProcessing(job,slide)}if(job.status==='done'){renderCompleted(job,false,slide);clientEvent('enrichment_rendered_done',{url,fullName:job.data?.fullName||null,company:job.data?.company||null,creditDelta:job.creditDelta??null,beforeCredits:job.beforeCredits??null,afterCredits:job.afterCredits??null,routeId:job.routeId||null});checkConnection('post_enrichment').catch(()=>{});toast(job.creditDelta===1?'Contact enriched — 1 credit observed.':'Contact enriched and saved.')}else if(['submitting','processing'].includes(job.status)){renderProcessing(job,slide);clientEvent('poll_loop_limit_reached',{url,status:job.status});toast('Still processing. No second research request was submitted.')}else{renderFailure(job,slide);clientEvent('enrichment_rendered_failure',{url,status:job.status,message:job.message||null})}}
async function enrich(){
  if(state.busy){clientEvent('enrich_click_ignored',{reason:'busy'});return}const input=$('linkedin');const url=validLinkedIn(input.value.trim());if(!url){clientEvent('enrich_validation_failed',{valueLength:input.value.trim().length});return toast('Paste a LinkedIn person URL such as https://www.linkedin.com/in/name/.')}state.busy=true;clientEvent('enrich_clicked',{url});$('send').disabled=true;$('send').innerHTML='<span>Enriching</span><span class="spinner"></span>';const slide=newSlide(url);clientEvent('result_slide_created',{url,slideId:slide.id});slide.innerHTML='<div class="slide-card checking-card"><div class="searching-orb"><span></span></div><div><span class="section-kicker">CACHE FIRST</span><h2>Checking this profile…</h2><p>If it is new, Beast submits exactly one direct LinkedIn research request.</p></div></div>';
  try{clientEvent('lookup_request_started',{url});const lookup=await api('/v1/person/lookup',{linkedinUrl:url});state.lookup=lookup;clientEvent('lookup_response_received',{url,cached:Boolean(lookup.cached),readyToResearch:Boolean(lookup.readyToResearch),existingStatus:lookup.job?.status||null});if(lookup.cached&&lookup.job?.status==='done'){renderCompleted(lookup.job,true,slide);clientEvent('cached_contact_rendered',{url,fullName:lookup.job.data?.fullName||null,company:lookup.job.data?.company||null});input.select();return}if(lookup.job&&['processing','submitting'].includes(lookup.job.status)){await pollUntilDone(lookup.job,url,slide);input.select();return}if(lookup.job&&!lookup.readyToResearch){renderFailure(lookup.job,slide);clientEvent('existing_job_blocked_new_research',{url,status:lookup.job.status});input.select();return}renderProcessing({status:'submitting',normalizedUrl:url},slide);clientEvent('research_request_started',{url,expectedContacts:1,automaticRetry:false});const job=await api('/v1/person/research',{linkedinUrl:url});clientEvent('research_response_received',{url,status:job.status,routeId:job.routeId||null,keySource:job.keySource||null,requestIds:job.requestIds||[],beforeCredits:job.beforeCredits??null,afterCredits:job.afterCredits??null,creditDelta:job.creditDelta??null});await pollUntilDone(job,url,slide);input.select()}catch(err){const failure={status:'failed',normalizedUrl:url,message:err.message,diagnosticTrace:err.payload?.diagnosticTrace||[]};clientEvent('enrichment_exception',{url,message:err.message,payloadCode:err.payload?.code||null,diagnosticTraceCount:failure.diagnosticTrace.length});registerJob(slide,failure);slide.innerHTML=`<div class="slide-card failure-card"><div class="error-icon">!</div><div><span class="section-kicker">REQUEST STOPPED</span><h2>Could not enrich this profile</h2><p>${esc(err.message)}</p></div></div>`;toast(err.message)}finally{state.busy=false;$('send').disabled=false;$('send').innerHTML='<span>Enrich</span><span>→</span>';clientEvent('enrich_action_finished',{url})}
}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();enrich()});
$('result-feed').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const slide=b.closest('.result-slide');if(b.dataset.companyContext!==undefined&&slide){const rec=state.records.get(slide.id);if(!rec?.job?.data)return;rec.companyContext=Number(b.dataset.companyContext)||0;slide.querySelectorAll('.company-option').forEach(x=>x.classList.toggle('selected',x===b));const note=slide.querySelector('.company-context-note');if(note)note.innerHTML=selectedCompanyNote(rec.job.data,rec.companyContext);return}if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Copied to clipboard')}catch{toast('Copy is unavailable in this browser.')}}});
$('credits').onclick=async()=>{clientEvent('credits_indicator_clicked',{previousDisplayedTotal:state.credits?.totalCreditsRemaining??null});await checkConnection('credits_click').catch(()=>{});$('credits-dialog').showModal()};$('credits-close').onclick=()=>$('credits-dialog').close();
function prospectRoleList(){return state.prospect.groups?.[state.prospect.group]||[]}
function prospectSelectedRoles(){return prospectRoleList().filter(r=>state.prospect.selected.has(r.id))}
function renderProspectRoles(reset=false){const roles=prospectRoleList();if(reset)state.prospect.selected=new Set(roles.map(r=>r.id));$('prospect-role-grid').innerHTML=roles.map(r=>`<label class="role-card ${state.prospect.group==='flagged'?'flagged':''} ${state.prospect.selected.has(r.id)?'selected':''}" data-role-id="${esc(r.id)}"><input type="checkbox" ${state.prospect.selected.has(r.id)?'checked':''}><div class="role-card-top"><strong>${esc(r.label)}</strong><span class="role-check">✓</span></div><small>${r.aliasCount} title variants</small></label>`).join('');updateProspectSelectionCount()}
function updateProspectSelectionCount(){const chosen=prospectSelectedRoles(),aliases=chosen.reduce((n,r)=>n+(r.aliasCount||0),0);$('role-selection-count').textContent=`${chosen.length} roles · ${aliases} title variants`}
async function initProspecting(){if(state.prospect.loaded)return;try{const data=await api('/v1/prospect/roles');state.prospect.groups=data.groups;state.prospect.capabilities=data.capabilities||null;state.prospect.loaded=true;renderProspectRoles(true);const direct=data.capabilities?.linkedinDirect,cs=direct?.session?.circuit?.state||'CLOSED';if($('prospect-engine-status'))$('prospect-engine-status').textContent=direct?.configured?`LinkedIn Direct (${direct.transport}) · persistent session · circuit ${cs} + OSINT`:'OSINT active · LinkedIn Direct not configured';clientEvent('prospecting_roles_loaded',{flagged:data.groups?.flagged?.length||0,notFlagged:data.groups?.not_flagged?.length||0,linkedinDirect:direct?.configured===true,transport:direct?.transport||null})}catch(error){$('prospect-role-grid').innerHTML=`<div class="role-loading">Could not load role intelligence: ${esc(error.message)}</div>`}}
function setProspectGroup(group){if(!['flagged','not_flagged'].includes(group))return;state.prospect.group=group;document.querySelectorAll('[data-role-group]').forEach(b=>{b.classList.toggle('active',b.dataset.roleGroup===group);b.classList.toggle('flagged',b.dataset.roleGroup==='flagged')});renderProspectRoles(true)}
function prospectSources(row){const engines=[...new Set((row.sources||[]).map(s=>s.engine))];return engines.map(e=>`<i>${esc(e)}</i>`).join('')}
function renderProspectSummary(job){const s=job.summary||{employees:job.results?.length||0,highConfidence:(job.results||[]).filter(r=>r.roleConfidence>=90&&r.currentEmploymentConfidence>=80).length,likelyCurrent:(job.results||[]).filter(r=>r.currentEmploymentConfidence>=80).length,directLinkedIn:(job.results||[]).filter(r=>r.directLinkedIn).length};$('prospect-summary').hidden=false;$('prospect-summary').innerHTML=`<div class="prospect-stat"><span>Employees found</span><strong>${Number(s.employees||0).toLocaleString()}</strong></div><div class="prospect-stat"><span>High confidence</span><strong>${Number(s.highConfidence||0).toLocaleString()}</strong></div><div class="prospect-stat"><span>Likely current</span><strong>${Number(s.likelyCurrent||0).toLocaleString()}</strong></div><div class="prospect-stat"><span>LinkedIn Direct</span><strong>${Number(s.directLinkedIn||0).toLocaleString()}</strong></div>`}
function renderProspectProgress(job){const p=job.progress||{},done=p.engineCallsCompleted||0,total=p.engineCallsPlanned||0,percent=total?Math.min(100,Math.round(done*100/total)):0;const running=job.status==='running',ld=p.linkedinDirect||{};const circuit=ld.session?.circuit?.state||'',rate=ld.session?.rate||{},directNote=ld.configured?` · LinkedIn Direct ${esc(ld.status||'queued')} · ${ld.requests||0} req · ${ld.partitions||0} partitions${circuit?` · circuit ${esc(circuit)}`:''}${rate.requestsLastMinute!=null?` · ${rate.requestsLastMinute}/${rate.maxPerMinute} req/min`:''}`:'';$('prospect-progress').className=`prospect-progress ${running?'running':''}`;$('prospect-progress').innerHTML=`<div class="prospect-progress-icon">${running?'↻':'✓'}</div><div><strong>${esc(running?(p.stage||'Discovering employees'):(job.status==='done'?'Discovery complete':'Prospecting stopped'))}</strong><span>${running?`${esc(p.currentRole||'Preparing roles')} · ${esc(p.currentEngine||'planner')} · ${p.uniqueEmployees||0} unique employees${directNote}`:`${(job.results||[]).length} unique LinkedIn profiles found for ${esc(job.company||'company')} · ${p.adaptivePartitions||0} adaptive partitions`}</span><div class="progress-line"><span style="width:${percent}%"></span></div></div>`;renderProspectSummary(job)}
function prospectFiltered(){const q=($('prospect-filter')?.value||'').trim().toLowerCase(),role=$('prospect-role-filter')?.value||'',min=Number($('prospect-confidence-filter')?.value||0);return (state.prospect.results||[]).filter(r=>(!role||r.roleId===role)&&r.roleConfidence>=min&&r.currentEmploymentConfidence>=Math.max(0,min-10)&&(!q||`${r.name} ${r.title} ${r.company} ${r.roleLabel}`.toLowerCase().includes(q)))}
function renderProspectResults(){const rows=prospectFiltered();$('prospect-toolbar').hidden=state.prospect.results.length===0;const roleFilter=$('prospect-role-filter');const current=roleFilter.value;const roles=[...new Map((state.prospect.results||[]).map(r=>[r.roleId,{id:r.roleId,label:r.roleLabel}])).values()];roleFilter.innerHTML='<option value="">All roles</option>'+roles.map(r=>`<option value="${esc(r.id)}">${esc(r.label)}</option>`).join('');if(roles.some(r=>r.id===current))roleFilter.value=current;if(!rows.length){$('prospect-results').innerHTML=`<div class="prospect-no-results"><strong>${state.prospect.results.length?'No people match these filters.':'No matching LinkedIn employees found yet.'}</strong><span>${state.prospect.job?.status==='running'?'The discovery job is still running. Results appear here as they are found.':'Try selecting more role families or another company spelling.'}</span></div>`;return}$('prospect-results').innerHTML=rows.map(r=>{const roleClass=r.roleConfidence>=90?'high':'medium',currentClass=r.currentEmploymentConfidence>=80?'high':'medium';return`<article class="prospect-person"><div class="person-main"><strong>${esc(r.name||'LinkedIn member')}</strong><a href="${esc(r.linkedinUrl)}" target="_blank" rel="noopener">${esc(r.linkedinUrl.replace(/^https?:\/\/(www\.)?/,'').replace(/\/$/,''))}</a></div><div class="person-title"><strong>${esc(r.title||'Title from public search evidence')}</strong><span>${esc(r.company||'')}</span><div class="source-mini">${prospectSources(r)}</div></div><span class="role-match-pill" title="Matched via ${esc(r.matchedAlias||r.roleLabel)}">${esc(r.roleLabel)} · ${r.roleConfidence}%</span><div class="confidence-stack ${currentClass}"><span>CURRENT EMPLOYEE</span><strong>${r.currentEmploymentConfidence}%</strong></div><a class="linkedin-open" href="${esc(r.linkedinUrl)}" target="_blank" rel="noopener">Open LinkedIn ↗</a></article>`}).join('')}
function acceptProspectJob(job){state.prospect.job=job;state.prospect.results=job.results||[];renderProspectProgress(job);renderProspectResults()}
async function pollProspecting(jobId){if(state.prospect.polling)return;state.prospect.polling=true;try{for(let i=0;i<600;i++){await new Promise(r=>setTimeout(r,i?1400:250));const job=await api(`/v1/prospect/status?jobId=${encodeURIComponent(jobId)}`);acceptProspectJob(job);if(job.status!=='running'){clientEvent('prospecting_finished',{jobId,status:job.status,employees:job.results?.length||0,errors:job.errors?.length||0});if(job.status==='done')toast(`Prospecting complete — ${job.results?.length||0} employees found.`);else toast('Prospecting stopped. Open results for details.');break}}}catch(error){toast(error.message);clientEvent('prospecting_poll_failed',{jobId,message:error.message})}finally{state.prospect.polling=false;const b=$('prospect-start');b.disabled=false;b.innerHTML='<span>Find employees</span><span>→</span>'}}
async function startProspecting(){const company=$('prospect-company').value.trim(),roleIds=prospectSelectedRoles().map(r=>r.id);if(!company)return toast('Enter a company name.');if(!roleIds.length)return toast('Select at least one role.');const b=$('prospect-start');b.disabled=true;b.innerHTML='<span>Prospecting</span><span class="spinner"></span>';$('prospect-results').innerHTML='';$('prospect-summary').hidden=true;$('prospect-toolbar').hidden=true;clientEvent('prospecting_started',{company,group:state.prospect.group,roleCount:roleIds.length});try{const job=await api('/v1/prospect/start',{company,group:state.prospect.group,roleIds});state.prospect.jobId=job.jobId;acceptProspectJob(job);pollProspecting(job.jobId)}catch(error){b.disabled=false;b.innerHTML='<span>Find employees</span><span>→</span>';toast(error.message);clientEvent('prospecting_start_failed',{company,message:error.message})}}
function exportProspects(){const rows=prospectFiltered();if(!rows.length)return toast('No prospecting results to export.');const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const head=['Name','Title','Company','Role family','Role confidence','Current employee confidence','LinkedIn URL','Sources'];const csv=[head.map(cell).join(','),...rows.map(r=>[r.name,r.title,r.company,r.roleLabel,r.roleConfidence,r.currentEmploymentConfidence,r.linkedinUrl,[...new Set((r.sources||[]).map(s=>s.engine))].join(' | ')].map(cell).join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`beast-prospects-${(state.prospect.job?.company||'company').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()}-${Date.now()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);clientEvent('prospecting_csv_exported',{rows:rows.length})}
function wireProspecting(){document.querySelectorAll('[data-role-group]').forEach(b=>b.onclick=()=>setProspectGroup(b.dataset.roleGroup));$('roles-all').onclick=()=>{state.prospect.selected=new Set(prospectRoleList().map(r=>r.id));renderProspectRoles(false)};$('roles-none').onclick=()=>{state.prospect.selected=new Set();renderProspectRoles(false)};$('prospect-role-grid').addEventListener('change',e=>{const card=e.target.closest('.role-card');if(!card)return;const id=card.dataset.roleId;if(e.target.checked)state.prospect.selected.add(id);else state.prospect.selected.delete(id);card.classList.toggle('selected',e.target.checked);updateProspectSelectionCount()});$('prospect-form').addEventListener('submit',e=>{e.preventDefault();startProspecting()});$('prospect-filter').addEventListener('input',renderProspectResults);$('prospect-role-filter').addEventListener('change',renderProspectResults);$('prospect-confidence-filter').addEventListener('change',renderProspectResults);$('prospect-export').onclick=exportProspects}
function view(prospecting){$('enriching-view').hidden=prospecting;$('prospecting-view').hidden=!prospecting;$('enriching-nav').classList.toggle('active',!prospecting);$('prospecting-nav').classList.toggle('active',prospecting);$('page-label').textContent=prospecting?'Prospecting Studio':'Enrichment Studio';if(prospecting)initProspecting()}$('enriching-nav').onclick=()=>view(false);$('prospecting-nav').onclick=()=>view(true);$('logout').onclick=()=>location.replace('/');wireProspecting();
async function checkConnection(reason='manual'){clientEvent('status_refresh_started',{reason,previousDisplayedTotal:state.credits?.totalCreditsRemaining??null});try{const result=await api(`/status?reason=${encodeURIComponent(reason)}`);const providerOk=['READY','DEGRADED'].includes(result.seamless?.status);const ok=result.database?.status==='READY'&&providerOk;$('connection-label').textContent=ok?'Connected':'Needs attention';$('connect').classList.toggle('bad',!ok);if(result.credits)updateCredits(result.credits);clientEvent('status_refresh_completed',{reason,ok,seamlessStatus:result.seamless?.status||null,databaseStatus:result.database?.status||null,displayedTotal:result.credits?.totalCreditsRemaining??null,allFresh:result.credits?.allFresh===true,activeRouteId:result.credits?.activeRouteId||null})}catch(error){$('connection-label').textContent='Offline';$('connect').classList.add('bad');clientEvent('status_refresh_failed',{reason,message:error.message})}}$('connect').onclick=()=>checkConnection('connection_click');
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkConnection('visibility_resume').catch(()=>{})});
$('diagnostics').onclick=()=>{$('diagnostics-dialog').showModal();clientEvent('diagnostics_dialog_opened',{})};$('diagnostics-close').onclick=()=>$('diagnostics-dialog').close();$('diagnostics-copy').onclick=async()=>{try{const text=await copyDeepDiagnosticReport();$('diagnostics-summary').textContent=`Copied ${text.length.toLocaleString()} bytes · ${new Date().toLocaleTimeString()}`;toast('FULL diagnostic report copied')}catch(err){toast(err.message)}};$('diagnostics-download').onclick=downloadDeepDiagnosticReport;$('diagnostics-reset').onclick=async()=>{await resetDiagnosticSession('manual_reset');$('diagnostics-summary').textContent='Fresh diagnostic session started. No provider research was triggered.';await checkConnection('diagnostic_reset_baseline').catch(()=>{})};
(async()=>{await resetDiagnosticSession('workspace_load');try{const r=await fetch('/health',{cache:'no-store'}),h=await r.json();$('build-label').textContent=`v${h.version}`;clientEvent('health_loaded',{version:h.version,buildId:h.buildId,architecture:h.architecture})}catch{$('build-label').textContent='v42'}await checkConnection('workspace_load')})();

setInterval(()=>{if(document.visibilityState==='visible'&&!state.busy)checkConnection('auto_15s').catch(()=>{})},15000);
